"""Graded direct-quad pattern around one exposed free-end step.

Three quads meet the two step corners. Five-quad U-shaped bands grow away from
the short edge geometrically; ordinary strips cover the remainder of the cap.
Inputs are six ordered planar footprint landmarks, supplied by the caller.
This component is not yet a complete Bundle surface: it does not select those
landmarks, reconcile the interior seam sampling, or assign carriageway heights.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import boundary_quad_bridge_nodes as bridge

NAME = 'Prochitecture Streets / Graded free-cap step quads v1'
MAX_RINGS = 20
MAX_ROWS = 4096


def shape_good(g, mesh):
    """Positive quad corners and the common maximum edge-ratio limit."""
    index = g.node('GeometryNodeInputIndex', 'Final cap corner').outputs[0]
    pos = g.node('GeometryNodeInputPosition', 'Final cap coordinates').outputs[0]
    lengths = []
    for offset in range(4):
        points = []
        for k in (offset, (offset+1) % 4):
            corner = g.node('GeometryNodeOffsetCornerInFace', 'Quad metric corner')
            g.set(index, corner.inputs['Corner Index']); corner.inputs['Offset'].default_value = k
            vertex = g.node('GeometryNodeVertexOfCorner', 'Quad metric vertex')
            g.set(corner.outputs['Corner Index'], vertex.inputs['Corner Index'])
            points.append(g.sample(mesh, pos, vertex.outputs['Vertex Index'], 'FLOAT_VECTOR'))
        lengths.append(g.vector('DISTANCE', *points))
    low = high = lengths[0]
    for length in lengths[1:]:
        low = g.math('MINIMUM', low, length); high = g.math('MAXIMUM', high, length)
    return g.all(bridge._mesh_good(g, mesh), g.compare(g.stat(mesh,
        g.math('DIVIDE', high, low), domain='CORNER', output='Max'), 8., 'LESS_EQUAL'))


