    step = g.vector('LENGTH', delta)
    forward = g.vector('NORMALIZE', delta)
    across = g.vector('CROSS_PRODUCT', (0., 0., 1.), forward)
    reflected = g.compare(g.vector('DOT_PRODUCT', g.vector('SUBTRACT', inp.outputs['Top'],
                         inp.outputs['Concave']), across), 0., 'LESS_THAN')
