    top, bottom, cut_top, cut_bottom = [local(inp.outputs[n]) for n in ('Top', 'Bottom', 'Cut Top', 'Cut Bottom')]
    x = lambda p: g.component(p, 'X')
    y = lambda p: g.component(p, 'Y')
    upper, lower = y(top), mul(-1., y(bottom))
    su, sl = div(sub(x(top), step), upper), div(x(bottom), y(bottom))
    slope = div(sub(x(cut_top), x(cut_bottom)), sub(y(cut_top), y(cut_bottom)))
    intercept = sub(x(cut_top), mul(slope, y(cut_top)))
    radius = g.math('MINIMUM', sub(intercept, step), mul(.5, g.math('MINIMUM', upper, lower)))
    seam_checks = []
    if prescribed_seam:
        # These are derived body seam records, not authored street controls.
        # Ordering them along the physical cut retains exact original identities.
        seam = g.store(inp.outputs['Seam'], '_cap_seam_original', index, 'INT')
        order = g.node('GeometryNodeSortElements', 'Order exact body seam from top to bottom')
        order.domain = 'POINT'; g.set(seam, order.inputs['Geometry'])
        g.set(mul(-1., y(local(pos))), order.inputs['Sort Weight']); seam = order.outputs['Geometry']
        count = bridge._size(g, seam)
        def seam_point(at):
            return local(g.sample(seam, pos, at, 'FLOAT_VECTOR'))
        lookup = bridge._position(g, seam, g.xyz(0., y(local(pos))))
        nearest = g.node('GeometryNodeSampleNearest', 'Body cut vertex nearest the step centre')
        nearest.domain = 'POINT'; g.set(lookup, nearest.inputs['Geometry'])
        # Sample Position otherwise has an implicit Position field, which
        # would choose a different centre for each generated vertex.
