        middle = nearest.outputs['Index']
        near_top, near_bottom = y(seam_point(sub(middle, 1.))), y(seam_point(add(middle, 1.)))
        radius = g.math('MINIMUM', radius, g.math('MINIMUM', near_top, mul(-1., near_bottom)))
        previous_y = y(seam_point(g.math('MAXIMUM', 0., sub(index, 1.))))
