        seam_checks = [g.compare(count, 5., 'GREATER_EQUAL'),
            g.compare(middle, 2., 'GREATER_EQUAL'), g.compare(middle, sub(count, 3.), 'LESS_EQUAL'),
            g.compare(near_top, 0., 'GREATER_THAN'), g.compare(near_bottom, 0., 'LESS_THAN'),
            g.stat(seam, monotone), g.compare(g.stat(seam, residual, output='Max'), 4e-6, 'LESS_EQUAL'),
            g.compare(g.stat(seam, g.math('ABSOLUTE', g.component(pos, 'Z')), output='Max'), 1e-7, 'LESS_EQUAL'),
            g.compare(g.vector('DISTANCE', seam_point(0), cut_top), 4e-6, 'LESS_EQUAL'),
            g.compare(g.vector('DISTANCE', seam_point(sub(count, 1.)), cut_bottom), 4e-6, 'LESS_EQUAL')]
